(1, 1, 'CREATE GROUP ', 'active', 28, '2026-05-20 13:16:44', NULL),
(2, 1, 'GET DRAWINGS FROM ARCHITECT OR CLIENT   ', 'active', 28, '2026-05-20 13:17:06', NULL),
