(12, 4, 'USE HIGH-QUALITY PURE COPPER & PVC COATING, COMPATIBLE CABLES, ENSURE PROPER EARTHING', 'active', 28, '2026-05-21 06:07:37', NULL),
(13, 4, 'INSTALL SEPARATE CONDUIT FOR SPEAKER CABLES, AWAY FROM POWER CABLES', 'active', 28, '2026-05-21 06:07:43', NULL),
