(16, 4, 'SCREEN MARKING AS PER DRAWING', 'active', 28, '2026-05-21 06:09:02', NULL),
(17, 4, 'LEAVE EXTRA LENGTH FOR ALL SIGNAL WIRES', 'active', 28, '2026-05-21 06:09:13', NULL),
(18, 4, 'MAIN SWITCHBOARD, INTERNET & NETWORK LAYOUT, SOCKET POSITIONS, MOTORIZED CURTAIN/BLIND CONTROL POINTS.', 'active', 28, '2026-05-21 06:09:26', NULL),
(19, 4, 'SCREEN WALL MUST BE PERFECTLY STRAIGHT, LEVEL, AND SMOOTH — NO BENDS, CURVES, OR UNEVEN SURFACES.', 'active', 28, '2026-05-21 06:09:52', NULL),
(20, 4, 'CABLE ROUTING & PIPE PATHS.', 'active', 28, '2026-05-21 06:10:14', NULL),
(21, 4, 'CONFIRM AC CAPACITY & AIRFLOW', 'active', 28, '2026-05-21 06:10:24', NULL),
(22, 4, 'FOLLOW FRAMING DRAWING DETAILS EXACTLY AS PER FINAL APPROVED LAYOUT', 'active', 28, '2026-05-21 06:10:34', NULL),
(23, 4, 'CONFIRM FROM CLIENT WHICH MATERIAL THEY ARE USING FOR CEILING AND WALL FRAMING.', 'active', 28, '2026-05-21 06:10:45', NULL),
(24, 4, 'USE 12 MM PLYWOOD FOR CEILING SPEAKER BOX WITH SLAB SUPPORT, AND PROVIDE VENTILATION GAP TO PREVENT OVERHEATING', 'active', 28, '2026-05-21 06:11:02', NULL),
(25, 4, 'CEILING OR WALL FRAMING SHOULD BE MADE STRONG TO PREVENT VIBRATION. IF USING ALUMINIUM OR GI FRAMING, USE EXTRA SCREWS AT CLOSER INTERVALS AND RUBBER WASHERS TO CREATE STRONG AND STABLE JOINTS.', 'active', 28, '2026-05-21 06:11:13', NULL),
(26, 4, 'FOLLOW EXACT PLATFORM HEIGHT AND STEP DETAIL AS PER DRAWING, USE SOLID FRAMING SUPPORT WITH PLYWOOD TOP, FILL INSIDE WITH ACOUSTIC INSULATION IF REQUIRED FOR SOUND DAMPENING, AND CHECK LEVEL AND STABI', 'active', 28, '2026-05-21 06:11:23', NULL),
(27, 4, 'MAKE SURE THE RACK HAS PROPER AIR CIRCULATION PROVISION BY PROVIDING ADEQUATE VENTILATION GAPS AND INSTALLING GRILL OR MESH COVERS AT INLET AND OUTLET POINTS', 'active', 28, '2026-05-21 06:11:41', NULL),
(28, 4, 'PROVIDE 2-STEP AT EDGE (KHATAKI) AND LAYERS OF ACOUSTIC DOOR TO PREVENT SOUND LEAKAGE.', 'active', 28, '2026-05-21 06:11:51', NULL),
(29, 4, 'PROVIDE SEAL AT BOTTOM, TOP, AND ON FRAME SIDES FOR SOUNDPROOFING, ENSURING SMOOTH DOOR CLOSING AND PROPER ALIGNMENT.', 'active', 28, '2026-05-21 06:12:03', NULL),
(30, 4, 'FOLLOW FINAL HOME THEATER LAYOUT CAREFULLY, INCLUDING LEVELS, SPEAKER POSITIONS, PROJECTOR LAYOUT, ALL CEILING LAYOUT DETAILS LIGHTS.', 'active', 28, '2026-05-21 06:12:12', NULL),
(31, 4, 'FOR CEILING CHANNELS, USE HIGH-QUALITY MATERIAL, EXTRA SCREWS, AND ADDITIONAL GRID SUPPORT TO PREVENT VIBRATION.', 'active', 28, '2026-05-21 06:12:20', NULL),
(32, 4, 'AVOID ANY GAPS OR UNEVEN FINISH THAT MAY AFFECT SOUND OR VISUAL PERFORMANCE.', 'active', 28, '2026-05-21 06:12:28', NULL),
(33, 4, 'KEEP ADEQUATE ACCESS PANELS FOR FUTURE MAINTENANCE (E.G., SPEAKER BOXES, PROJECTOR AREA, STAR CEILING, OR FIBER OPTIC SYSTEMS).', 'active', 28, '2026-05-21 06:12:34', NULL),
