INSERT INTO `process_execution` (`process_id`, `process_name`, `description`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'CREATE GROUP', 'RECLINERS COUNT, FRAMING, SPEAKER LOCATION, SCREEN SIZE, PROJECTOR DISTANCE', 'active', 28, '2026-05-19 12:59:00', '2026-05-20 18:45:19'),
(2, 'GET DRAWINGS FROM ARCHITECT OR CLIENT', 'ABOUT DOOR, WINDOW, BEAM, COLUMN, CEILING ELECTRICAL LAYOUT, LIGHTING LAYOUT.', 'active', 28, '2026-05-19 12:59:22', NULL),
(3, 'MAKE BASIC LAYOUT', 'NAME OF CLIENT, CITY & AV CORE (EX: JAMTANI GROUP | PUNE | AVCORE)', 'active', 28, '2026-05-19 12:59:36', NULL),
(4, 'CONFIGURATION OF AUDIO VIDEO SYSTEM', 'CKECK CONFIGURATION OF AUDIO & VIDEO FROM QUOTATION (EX: 5.1.2, 7.1.2), CHECK MODEL NO OF\nAUDIO & VIDEO\n', 'active', 28, '2026-05-19 13:00:49', NULL),
(5, 'DIMENTIONS OF AUDIO VIDEO ', 'SPEAKERS, SCREEN, SUBWOOFER, PROJECTOR DISTANCE.', 'active', 28, '2026-05-19 13:01:12', '2026-05-21 12:32:49'),
(6, 'ACOUSTIC DETAILS', 'ACOUSTIC WALL DETAILS, 2\' X 2\' ACOUSTIC FRAMING, ACOUSTIC INFILL, 12 MM PERFORATED MDF,\nFINISHING WITH12 MM FOAM & FABRIC\nACOUSTIC DOOR DETAILS, WINDOW DETAILS, PLATFORM HEIGHT, PLYWOOD OR MDF, OUTSIDE &\nINSIDE VENEER OR FABRIC FINISH.\n', 'active', 28, '2026-05-19 13:01:43', '2026-05-21 12:34:17'),
(8, 'GET DRAWING APPROVAL FROM CLIENT SIDE', 'GET FINAL DRAWING APPROVAL FROM CLIENT SIDE', 'active', 28, '2026-05-20 19:29:17', '2026-05-21 11:35:10'),
(9, 'GET DRAWING APPROVAL FROM ARCHITECT SIDE', 'GET FINAL DRAWING APPROVAL FROM ARCHITECT SIDE', 'active', 28, '2026-05-20 19:29:47', NULL),
(10, 'ALL CABLES & PROJECTOR BRACKET DELIVERY  ', NULL, 'active', 28, '2026-05-20 19:31:29', NULL),
(11, 'USE HIGH-QUALITY PURE COPPER & PVC COATING, COMPATIBLE CABLES, ENSURE PROPER EARTHING', NULL, 'active', 28, '2026-05-20 19:32:03', NULL),
(12, 'INSTALL SEPARATE CONDUIT FOR SPEAKER CABLES, AWAY FROM POWER CABLES ', NULL, 'active', 28, '2026-05-20 19:32:22', NULL),
(13, 'USE SEPARATE, OVERSIZED PIPE FOR HDMI CABLE FOR EASY REMOVAL AND REPLACEMENT ', NULL, 'active', 28, '2026-05-20 19:32:34', NULL),
(14, 'PROJECTOR BRACKET FIXING', NULL, 'active', 28, '2026-05-20 19:32:44', NULL),
(15, 'SCREEN MARKING AS PER DRAWING ', NULL, 'active', 28, '2026-05-20 19:32:54', NULL),
(16, 'LEAVE EXTRA LENGTH FOR ALL SIGNAL WIRES', NULL, 'active', 28, '2026-05-20 19:33:02', NULL),
(17, 'MAIN SWITCHBOARD, INTERNET & NETWORK LAYOUT, SOCKET POSITIONS, MOTORIZED CURTAIN/BLIND CONTROL POINTS.', NULL, 'active', 28, '2026-05-20 19:33:15', NULL),
(18, 'SCREEN WALL MUST BE PERFECTLY STRAIGHT, LEVEL, AND SMOOTH — NO BENDS, CURVES, OR UNEVEN SURFACES.', NULL, 'active', 28, '2026-05-20 19:33:25', NULL),
(19, 'CABLE ROUTING & PIPE PATHS.', NULL, 'active', 28, '2026-05-20 19:33:37', NULL),
(20, 'CONFIRM AC CAPACITY & AIRFLOW', NULL, 'active', 28, '2026-05-20 19:33:48', NULL),
(21, 'FOLLOW FRAMING DRAWING DETAILS EXACTLY AS PER FINAL APPROVED LAYOUT', NULL, 'active', 28, '2026-05-20 19:34:52', NULL),
(22, 'CONFIRM FROM CLIENT WHICH MATERIAL THEY ARE USING FOR CEILING AND WALL FRAMING.', NULL, 'active', 28, '2026-05-20 19:35:04', NULL),
(23, 'USE 12 MM PLYWOOD FOR CEILING SPEAKER BOX WITH SLAB SUPPORT, AND PROVIDE VENTILATION GAP TO PREVENT OVERHEATING', NULL, 'active', 28, '2026-05-20 19:35:13', NULL),
(24, 'CEILING OR WALL FRAMING SHOULD BE MADE STRONG TO PREVENT VIBRATION. IF USING ALUMINIUM OR GI FRAMING, USE EXTRA SCREWS AT CLOSER INTERVALS AND RUBBER WASHERS TO CREATE STRONG AND STABLE JOINTS.', NULL, 'active', 28, '2026-05-20 19:35:29', NULL),
(25, 'FOLLOW EXACT PLATFORM HEIGHT AND STEP DETAIL AS PER DRAWING, USE SOLID FRAMING SUPPORT WITH PLYWOOD TOP, FILL INSIDE WITH ACOUSTIC INSULATION IF REQUIRED FOR SOUND DAMPENING, AND CHECK LEVEL AND STABILITY BEFORE FLOORING FINISH. ', NULL, 'active', 28, '2026-05-20 19:35:39', NULL),
(26, 'MAKE SURE THE RACK HAS PROPER AIR CIRCULATION PROVISION BY PROVIDING ADEQUATE VENTILATION GAPS AND INSTALLING GRILL OR MESH COVERS AT INLET AND OUTLET POINTS', NULL, 'active', 28, '2026-05-20 19:35:51', NULL),
(27, 'PROVIDE 2-STEP AT EDGE (KHATAKI) AND LAYERS OF ACOUSTIC DOOR TO PREVENT SOUND LEAKAGE. ', NULL, 'active', 28, '2026-05-20 19:36:04', NULL),
(28, 'PROVIDE SEAL AT BOTTOM, TOP, AND ON FRAME SIDES FOR SOUNDPROOFING, ENSURING SMOOTH DOOR CLOSING AND PROPER ALIGNMENT.', NULL, 'active', 28, '2026-05-20 19:36:38', NULL),
(29, 'FOLLOW FINAL HOME THEATER LAYOUT CAREFULLY, INCLUDING LEVELS, SPEAKER POSITIONS, PROJECTOR LAYOUT, ALL CEILING LAYOUT DETAILS LIGHTS.', NULL, 'active', 28, '2026-05-20 19:36:53', NULL),
(30, 'FOR CEILING CHANNELS, USE HIGH-QUALITY MATERIAL, EXTRA SCREWS, AND ADDITIONAL GRID SUPPORT TO PREVENT VIBRATION. ', NULL, 'active', 28, '2026-05-20 19:37:02', NULL),
(31, 'AVOID ANY GAPS OR UNEVEN FINISH THAT MAY AFFECT SOUND OR VISUAL PERFORMANCE.', NULL, 'active', 28, '2026-05-20 19:37:29', NULL),
(32, 'KEEP ADEQUATE ACCESS PANELS FOR FUTURE MAINTENANCE (E.G., SPEAKER BOXES, PROJECTOR AREA, STAR CEILING, OR FIBER OPTIC SYSTEMS). ', NULL, 'active', 28, '2026-05-20 19:37:41', NULL),
